        'zabbix_blurb' => 'মনিটরিং সমস্যা নিজে থেকেই ঘটনা খোলে, পুনরাবৃত্তি সেগুলোতে যোগ হয় এবং পুনরুদ্ধার সেগুলো সমাধান করে।',
        'zabbix_intro' => 'Zabbix কোনো সমস্যা ধরলে - যেমন ডিস্ক ভরে যাচ্ছে, সার্ভার সাড়া দিচ্ছে না - এখানে একটি ঘটনা তৈরি করে, যা CMDB-র সেই সার্ভারের সাথে লিঙ্ক করা থাকে। একই সমস্যা আবার জানালে তা একই টিকিটে যায়। সমস্যা মিটে গেলে টিকিট সমাধান হয়ে যায়।',
        'zabbix_direction' => 'Zabbix FreeITSM-কে কল করে - FreeITSM কখনো Zabbix-এ সংযোগ করে না, তাই Zabbix-এর ঠিকানা বা Zabbix পাসওয়ার্ড লাগে না। Zabbix-এর যা দরকার সব নিচে আছে।',
        'zabbix_not_ready' => 'আগে System → Database Verification চালান: এটি এই ইন্টিগ্রেশনের ইভেন্ট লগ রাখার টেবিল তৈরি করে।',
        'zabbix_connect' => 'Zabbix সংযোগ করুন',
        'zabbix_connect_body' => 'Zabbix প্রতিটি অ্যালার্ট সিক্রেট টোকেনসহ নিচের ঠিকানায় পাঠায়। Zabbix-এ Alerts → Media types → Create media type-এ যান, Webhook বেছে নিন, নাম দিন FreeITSM, নিচের প্যারামিটার ও স্ক্রিপ্ট পেস্ট করুন, তারপর এটি একজন ব্যবহারকারী এবং Alerts → Actions → Trigger actions-এর একটি অ্যাকশনে যোগ করুন। অ্যাকশনে "Recovery operations" টিক দিন, নইলে টিকিট কখনো সমাধান হবে না।',
        'zabbix_endpoint' => 'FreeITSM-এর ঠিকানা (এটি Zabbix-কে দিন)',
        'zabbix_import' => 'দ্রুততম: Zabbix-এ ইমপোর্ট করুন',
        'zabbix_import_body' => 'সবকিছু পূরণ করা মিডিয়া টাইপটি ডাউনলোড করুন - উপরের ঠিকানা, আপনার টোকেন, স্ক্রিপ্ট ও তিনটি বার্তার টেমপ্লেট - তারপর Zabbix-এ Alerts → Media types → Import-এ গিয়ে ফাইলটি বেছে নিন। এরপর এটি একজন ব্যবহারকারীকে দিন এবং একটি অ্যাকশন যোগ করুন (গাইডের ৪ নম্বর ধাপ)।',
