        'zabbix_token_rotate' => 'নতুন টোকেন',
        'zabbix_rotate_confirm' => 'নতুন টোকেন তৈরি করবেন? পুরনোটি সাথে সাথে কাজ করা বন্ধ করবে, তাই নতুনটি Zabbix-এর মিডিয়া টাইপে পেস্ট না করা পর্যন্ত Zabbix ব্যর্থ হবে।',
        'zabbix_params' => 'মিডিয়া টাইপের প্যারামিটার',
        'zabbix_params_hint' => 'নতুন ওয়েবহুকের জন্য Zabbix যে প্যারামিটারগুলো পূরণ করে (URL, HTTPProxy, To, Subject, Message) সেগুলো মুছে ফেলুন - ওগুলো তার উদাহরণ স্ক্রিপ্টের, এটির নয়। তারপর এখানকার প্রতিটি লাইন একটি প্যারামিটার হিসেবে যোগ করুন: বাঁদিকে নাম, ডানদিকে মান। আপনার Zabbix সার্ভার শুধু প্রক্সির মাধ্যমে FreeITSM-এ পৌঁছাতে পারলে ছাড়া http_proxy ফাঁকা থাকে। ব্রেসের ভেতরের মানগুলো Zabbix ম্যাক্রো - যেমন আছে তেমনই রাখুন। url লাইনটি প্রতিটি টিকিটকে Zabbix-এ সমস্যার একটি লিঙ্ক দেয়; এর জন্য ম্যাক্রো {$ZABBIX.URL} আপনার Zabbix ওয়েব ঠিকানায় সেট থাকতে হবে (Zabbix: Administration → Macros)। এটি না থাকলে টিকিটে শুধু কোনো লিঙ্ক থাকে না।',
        'zabbix_script' => 'মিডিয়া টাইপের স্ক্রিপ্ট',
        'zabbix_copy' => 'কপি',
        'zabbix_copied' => 'কপি হয়েছে।',
        'zabbix_reach_hint' => 'যেখানে Zabbix অ্যালার্ট পাঠাবে। এটি শুরুতে আপনার পাবলিক বেস URL থাকে; Zabbix একই সার্ভারে বা নেটওয়ার্কে থাকলে FreeITSM-এ যাওয়ার পথ ভিন্ন হতে পারে - এই মেশিনে Docker-এ থাকা Zabbix-এর জন্য http://host.docker.internal/ এবং বাকি পথ। এখানে বদলালে প্যারামিটার ও ডাউনলোড সেটি অনুসরণ করবে।',
        'zabbix_tickets' => 'যে ঘটনাগুলো এটি তৈরি করে',
        'zabbix_requester' => 'যার নামে তৈরি',
        'zabbix_requester_hint' => 'যে অনুরোধকারীর কাছ থেকে টিকিট আসে। ডিফল্টটি কখনো মেইল পেতে পারে না, তাই অ্যালার্টের জন্য কাউকে ইমেল করা হয় না; স্বীকৃতি কোথাও পাঠাতে চাইলে একটি আসল মনিটরিং মেইলবক্স ব্যবহার করুন।',
