        'zabbix_link_cmdb' => 'Zabbix হোস্টের নামের মতো নামের CMDB আইটেম লিঙ্ক করুন',
        'zabbix_link_cmdb_hint' => 'আগে পুরো নাম, তারপর ছোট নাম (web01.example.com-এর জন্য web01)। দুটি কোম্পানিতেই মিল থাকলে কোনোটিই লিঙ্ক হয় না।',
