        'zabbix_act_error' => 'ব্যর্থ',
        'zabbix_recovery' => 'পুনরুদ্ধার',
        'zabbix_test' => 'চেষ্টা করুন',
        'zabbix_test_body' => 'ইন্টিগ্রেশনের মধ্য দিয়ে একটি পরীক্ষামূলক সমস্যা পাঠায়, ঠিক Zabbix-এর আসল অ্যালার্টের মতো করে সামলানো হয়: আপনার সেটিংস অনুযায়ী একটি ঘটনা তৈরি হয়, এবং তারপর এর পুনরুদ্ধার পাঠিয়ে সমাধান হতে দেখতে পারেন। পরীক্ষামূলক ঘটনাটি থেকে যায়, পরীক্ষা হিসেবে শিরোনামসহ, যাতে আসল ঘটনা কেমন দেখায় তা বুঝতে পারেন - অন্য যেকোনো টিকিটের মতো এটি বন্ধ করুন।',
        'zabbix_test_limit' => 'এটি FreeITSM-এর অর্ধেক পরীক্ষা করে। আপনার Zabbix সার্ভার FreeITSM-এ পৌঁছাতে পারে কি না সেটি বাকি অর্ধেক: Zabbix-এ মিডিয়া টাইপের Test বোতাম দিয়ে তা পরীক্ষা করুন।',
