        'msteams_blurb' => 'আপনার Teams চ্যানেলে কার্ড হিসেবে সার্ভিস ডেস্কের অ্যালার্ট - জরুরি টিকিট, SLA ভঙ্গ, প্রতিটি দলের টিকিট - সরাসরি টিকিটে যাওয়ার বোতামসহ।',
        'msteams_intro' => 'সার্ভিস ডেস্কের অ্যালার্ট Microsoft Teams চ্যানেলে কার্ড হিসেবে পোস্ট করুন, প্রতিটিতে একটি Open in FreeITSM বোতাম থাকে। প্রতিটি চ্যানেল কী কী জানবে তা টিক দিন: জরুরি টিকিট, SLA সতর্কতা ও ভঙ্গ, তার দলগুলোর টিকিট, স্ট্যাটাস পেজের ঘটনা, অপেক্ষমাণ অনুমোদন।',
