        'slack_watch_channel' => 'শুধু এই চ্যানেল নজরে রাখুন',
        'slack_watch_channel_hint' => 'C08ABCDEF-এর মতো একটি Slack চ্যানেল ID। অ্যাপকে আমন্ত্রণ জানানো প্রতিটি চ্যানেল থেকে টিকিট তৈরি করতে ফাঁকা রাখুন — ব্যস্ত চ্যানেলে এর মানে প্রতিটি বার্তার জন্য একটি টিকিট, তাই বেশিরভাগ মানুষ এখানে একটি সহায়তা চ্যানেলের নাম দেন।',
        'slack_company_shared' => 'শেয়ার করা — প্রেরক অনুযায়ী ঠিক হবে',
        'slack_company_hint' => 'এই ওয়ার্কস্পেসকে একটি কোম্পানিতে নির্দিষ্ট করুন, অথবা শেয়ার করা রাখুন এবং প্রেরককে ঠিক করতে দিন।',
        'slack_delete_confirm' => 'Slack ওয়ার্কস্পেস “{name}” মুছবেন? এর থেকে আগে তৈরি টিকিটগুলোর ইতিহাস থাকবে; শুধু নতুন বার্তা আসা বন্ধ হবে।',
        'slack_diag_title' => 'Slack হেলথ চেক',
        'slack_diag_desc' => 'যা নীরবে ভুল হতে পারে তার সবকিছু পরীক্ষা করে — শুধু টোকেন কাজ করছে কিনা তা নয়। প্রতিটি ফলাফল বলে দেয় কী করতে হবে।',
        'slack_diag_running' => 'পরীক্ষা চলছে — এটি Slack ও আপনার নিজের পাবলিক ঠিকানার সাথে কথা বলে, তাই কয়েক সেকেন্ড সময় দিন…',
