        'step_dns_title' => 'নামটি সার্ভারের দিকে নির্দেশ করুন',
        'step_dns_body' => 'PC-গুলোকে জানতে হবে যে {host} মানে {ip}। সবচেয়ে ভালো উপায় হলো আপনার নেটওয়ার্কের DNS সার্ভারে একটি DNS রেকর্ড যোগ করা (Windows ডোমেইনে DNS Manager-এ; ছোট নেটওয়ার্কে প্রায়ই রাউটারে):',
