        'step_dns_no_ip' => 'কোন রেকর্ড তৈরি করতে হবে তা ঠিকঠাক দেখতে উপরে সার্ভারের IP ঠিকানা পূরণ করুন।',
        'step_ca_title' => 'প্রতিটি PC-তে অথরিটি সার্টিফিকেট ইনস্টল করুন',
        'step_ca_body' => 'এটি PC-গুলোকে সার্টিফিকেটটি বিশ্বাস করতে বলে। প্রতিটি PC-তে একবারই করতে হয়, এবং নাম বা IP বদলালে আবার।',
        'download' => 'ডাউনলোড',
        'step_ca_windows' => 'Windows: ফাইলটিতে ডাবল-ক্লিক করুন, Install Certificate বেছে নিন, Local Machine নির্বাচন করুন, তারপর Place all certificates in the following store বেছে Trusted Root Certification Authorities নির্বাচন করুন।',
        'step_ca_gpo' => 'ডোমেইনে থাকা অনেক Windows PC: Group Policy-তে Computer Configuration → Policies → Windows Settings → Security Settings → Public Key Policies → Trusted Root Certification Authorities-এর অধীনে ফাইলটি একবার ইমপোর্ট করুন। Intune এটি Trusted certificate profile হিসেবে পুশ করতে পারে।',
        'step_ca_mac' => 'Mac: ফাইলটিতে ডাবল-ক্লিক করে Keychain Access-এ যোগ করুন, সেখানে খুলে When using this certificate-কে Always Trust করুন।',
        'step_ca_firefox' => 'Windows-এ Firefox স্বয়ংক্রিয়ভাবে Windows-এর সার্টিফিকেট ব্যবহার করে। তবুও সতর্কতা এলে about:config-এ security.enterprise_roots.enabled-কে true করুন।',
        'step_ca_safe' => 'এই অথরিটি শুধু {host}-এর পক্ষে নিশ্চয়তা দিতে পারে, অন্য কিছুর নয়, তাই এটি ইনস্টল করলে অন্য কোনো ওয়েবসাইটের ছদ্মবেশ ধরা সম্ভব হয় না।',
        'step_restart_title' => 'কন্টেইনার রিস্টার্ট করুন',
        'step_restart_body' => 'যে ফোল্ডারে আপনার docker-compose.yml আছে সেখানে {cmd} চালান।',
        'step_restart_done' => 'হয়ে গেছে: কন্টেইনার এই সার্টিফিকেট ব্যবহার করছে।',
        'step_open_title' => 'HTTPS দিয়ে FreeITSM খুলুন',
        'step_open_body' => '{url}-এ যান। লোড না হলে দেখুন আপনার docker-compose.yml পোর্ট 443 প্রকাশ করছে কিনা (স্ট্যান্ডার্ড ফাইলে এটি 8443-এ ম্যাপ করা)। সেটি বদলে থাকলে আপনার পোর্ট ব্যবহার করুন।',
        'proxy_heading' => 'রিভার্স প্রক্সির পিছনে',
        'proxy_intro' => 'FreeITSM-এর সামনে রিভার্স প্রক্সি, লোড ব্যালান্সার বা Cloudflare Tunnel থাকলে প্রতিটি রিকোয়েস্ট প্রক্সি থেকে FreeITSM-এ পৌঁছায়। কোন ঠিকানাটি প্রক্সি তা FreeITSM-কে না জানালে সে সবার জন্য প্রক্সির ঠিকানা রেকর্ড করে: রিপোর্টিং → লগে, অডিট ট্রেইলে, এবং কোনো API key যখন যাচাই করে কোন ঠিকানা অনুমোদিত।',
        'proxy_off_title' => 'বন্ধ',
        'proxy_off_body' => 'FreeITSM প্রতিটি সংযোগ যে ঠিকানা থেকে আসে সেটি রেকর্ড করে। মানুষ সরাসরি FreeITSM-এ সংযোগ করলে এটি ঠিক, কিন্তু প্রক্সির পিছনে ভুল - আপনার কোনটি তা দেখতে নিচের পরীক্ষা ব্যবহার করুন।',
        'proxy_on_title' => 'চালু',
        'proxy_on_body' => 'আসল ঠিকানা {header} হেডার থেকে নেওয়া হয়, কিন্তু শুধু {list} থেকে আসা রিকোয়েস্টে।',
        'proxy_refused_title' => 'সেট করা আছে, কিন্তু কার্যকর নয়',
        'proxy_refused_body' => 'TRUSTED_PROXIES {list} সেট করা আছে, কিন্তু কন্টেইনার চালু হওয়ার সময় এটি প্রত্যাখ্যান করা হয়েছে, তাই FreeITSM প্রতিটি সংযোগ যে ঠিকানা থেকে আসে সেটি রেকর্ড করে। কারণ দেখতে {cmd} চালান।',
        'proxy_wide_title' => 'সতর্কতা: এই সেটিং অতিরিক্ত বিস্তৃত',
        'proxy_wide_body' => '{ranges} একাধিক প্রক্সি কভার করে। এর ভেতরের যেকোনো মেশিন নিজেকে যেকোনো ঠিকানা বলে দাবি করতে পারে। TRUSTED_PROXIES প্রক্সির নিজস্ব ঠিকানায় বদলান এবং কন্টেইনার রিস্টার্ট করুন।',
        'proxy_danger_title' => 'ভুল সেটিং কী করে - বদলানোর আগে এটি পড়ুন',
        'proxy_danger_wide' => 'অতিরিক্ত বিস্তৃত - বিপজ্জনক ভুল। প্রক্সির হেডারের ঠিকানা FreeITSM শুধু আপনার তালিকাভুক্ত ঠিকানাগুলোর রিকোয়েস্টে বিশ্বাস করে, কারণ যে কেউ ওই হেডার লিখতে পারে। {example}-এর মতো কোনো রেঞ্জ বা পুরো Docker নেটওয়ার্ক তালিকাভুক্ত করলে এর ভেতরের যেকোনো মেশিন নিজেকে যেকোনো ঠিকানা বলে দাবি করতে পারে: সাইন-ইন লগ ও অডিট ট্রেইলে মিথ্যা ঠিকানা বসাতে পারে, এবং শুধু নির্দিষ্ট ঠিকানা অনুমোদনকারী API key-কে পাশ কাটাতে পারে। শুধু প্রক্সির নিজস্ব ঠিকানা তালিকাভুক্ত করুন।',
        'proxy_danger_missing' => 'প্রক্সি থাকা সত্ত্বেও সেট করা নেই। কিছু ভাঙে না, কিন্তু প্রতিটি সাইন-ইন ও প্রতিটি পরিবর্তন প্রক্সির ঠিকানা থেকে রেকর্ড হয়, তাই লগ থেকে মানুষকে আলাদা করা যায় না - এবং একটি API key-র অনুমোদিত ঠিকানায় শুধু প্রক্সির নাম দেওয়া যায়, যা প্রক্সি দিয়ে আসা যে কাউকে ঢুকতে দেয়।',
        'proxy_danger_wrong' => 'ভুল ঠিকানা। হেডার উপেক্ষা করা হয়, তাই আবার সবাই প্রক্সি হিসেবে রেকর্ড হয়। পরীক্ষা এটি সঙ্গে সঙ্গে দেখায়।',
        'proxy_how' => 'এটি docker-compose.yml-এ সেট করা হয়, এই পেজে নয়, এবং কন্টেইনার রিস্টার্ট হলে কার্যকর হয় (docker compose up -d):',
        'proxy_how_cf' => 'Cloudflare Tunnel-এর জন্য {setting}-ও সেট করুন। একাধিক প্রক্সি: স্পেস দিয়ে আলাদা করুন।',
