        'verdict_still_proxy' => 'কাজ করছে না: রেকর্ড হওয়া ঠিকানাটি প্রক্সি নিজেই, অর্থাৎ প্রক্সি {header} হেডার পাঠাচ্ছে না। প্রক্সিকে {header} যোগ করতে বলুন, অথবা TRUSTED_PROXY_HEADER-কে সে যে হেডার পাঠায় সেটিতে সেট করুন।',
        'verdict_refused' => 'সেটিংটি কার্যকর নয় (উপরে দেখুন), তাই FreeITSM প্রতিটি সংযোগ যে ঠিকানা থেকে আসে সেটি রেকর্ড করে। আগে সেটিং ঠিক করুন, তারপর আবার পরীক্ষা করুন।',
