        'health_never' => 'ক্যালেন্ডার কখনো যাচাই করা হয়নি।',
        'health_stale_note' => 'Outlook-এ করা পরিবর্তন নির্ধারিত জব চলার সময় আসে, তাই এর অর্থ সাধারণত সেটি থেমে গেছে &mdash; দেখুন <code>cron/calendar_sync_pull.php</code> নির্ধারিত সময়সূচিতে এখনও চলছে কিনা। সাবস্ক্রিপশন নবায়নও এটিই করে, তাই এটি থেমে গেলে কয়েক দিন পর বিজ্ঞপ্তিও বন্ধ হয়ে যায়। আপনি ইচ্ছা করে প্রতি আধ ঘণ্টার চেয়ে কম ঘন ঘন চালালে এটি প্রত্যাশিত।',
        'health_subs' => 'বিজ্ঞপ্তি: {total}-এর মধ্যে {n}টি সাবস্ক্রাইব করা।',
