        'field_portal_domains' => 'ইমেল ডোমেইন',
        'field_portal_domains_hint' => 'প্রতি লাইনে একটি, যেমন company.com। পোর্টালে এই ডোমেইনগুলোর কোনো একটির ইমেল ঠিকানা প্রথমবারেও সরাসরি এই প্রোভাইডারে যায়। এর মধ্যে সেই লোকেরাও আছেন যারা আজ পাসওয়ার্ড দিয়ে সাইন ইন করেন। বাকি সবাই যথারীতি পাসওয়ার্ড বক্স পান। সাবডোমেইনের জন্য আলাদা লাইন লাগে। কাউকে রাউট না করতে ফাঁকা রাখুন।',
