        'entra_sync_desc' => 'Entra ID থেকে ব্যক্তিদের তৈরি ও হালনাগাদ করে, যাতে কেউ সাইন ইন করার আগেই তারা থাকে। কাউকে কখনো মুছে ফেলা হয় না: যারা চলে যান তাদের লিভার হিসেবে চিহ্নিত করা হয়, আর হঠাৎ অনেক কম ব্যক্তি পেলে রান কিছু না বদলে থেমে যায়। ইমপোর্ট করা ব্যক্তিরা সঙ্গে সঙ্গে এই প্রদানকারী দিয়ে সাইন ইন করতে পারেন।',
