        'maint_page_title' => 'ইমপোর্ট করা ব্যক্তি',
        'maint_page_sub' => 'ডিরেক্টরি সোর্স - LDAP, অ্যাড্রেস বুক বা Microsoft Entra ID - যে ব্যক্তিদের ইমপোর্ট করেছে, যখন তাদের নিয়ে সিদ্ধান্ত দরকার: তাদের সোর্স মুছে ফেলা হয়েছে, আর তাদের আনছে না, অথবা তাদের ইমপোর্ট করাই উচিত ছিল না। টিকিট বা সরঞ্জাম আছে এমন কাউকে কখনো মুছে ফেলা হয় না, এবং এখানে করা সবকিছু সিস্টেম লগে রেকর্ড হয়।',
        'maint_source_heading' => 'একটি সোর্স',
        'maint_source_label' => 'সোর্স',
        'maint_deleted_kind' => 'মুছে ফেলা হয়েছে',
        'maint_deleted_hint' => 'এই সোর্স মুছে ফেলা হয়েছে, তাই এটি আর কাউকে আনে না। এর ইমপোর্টে তৈরি ব্যক্তিরা নিচে তালিকাভুক্ত, যদি না অন্য কোনো সোর্স এখন তাদের হালনাগাদ রাখে। যাদের এটি আগে থেকেই এখানে থাকা কারও সঙ্গে মিলিয়েছে তারা তালিকায় নেই।',
