        'openapi' => 'OpenAPI স্পেসিফিকেশন',
        'mcp' => 'AI অ্যাসিস্ট্যান্ট সংযুক্ত করুন (MCP)',
        'mcp_desc' => 'FreeITSM <strong>Model Context Protocol</strong> বোঝে, তাই Claude Code বা Claude Desktop-এর মতো একটি AI অ্যাসিস্ট্যান্ট প্রজেক্ট, খোলা ইনসিডেন্ট, সার্ভিস স্ট্যাটাস, পরিবর্তন, অ্যাসেট এবং আরও অনেক কিছু পড়তে পারে। এটি <strong>শুধু-পঠনযোগ্য</strong> এবং কী-এর বিশ্লেষক যা দেখতে পারেন ঠিক তাই দেখে: তাঁর মডিউল এবং কী-এর কোম্পানিগুলো। নিচে <strong>MCP server</strong> অনুমতি দিয়ে একটি কী তৈরি করুন এবং অ্যাসিস্ট্যান্টকে এই ঠিকানা দিন। <a href="https://github.com/edmozley/freeitsm/wiki/MCP-Server" target="_blank" rel="noopener">নির্দেশিকা</a> দেখুন।',
        'mcp_claude_code' => 'Claude Code-এর জন্য টার্মিনালে এটি চালান (YOUR_KEY-এর জায়গায় আপনার কী বসান):',
