        'del_int_help' => 'ওয়ার্কার যদি পাঠানোর মাঝখানে থেমে যায় - সার্ভার রিস্টার্ট বা শিডিউল্ড টাস্ক বন্ধ করে দেওয়া - তাহলে এন্ডপয়েন্ট পেয়েছে কি না কেউ জানে না। ১০ মিনিট পর FreeITSM এর নিষ্পত্তি করে: <strong>আবার চেষ্টা করুন</strong> এটিকে ব্যর্থ চেষ্টা গণ্য করে উপরের সময়সূচি অনুযায়ী আবার চেষ্টা করে; <strong>থামুন</strong> সঙ্গে সঙ্গে এটিকে ডেড চিহ্নিত করে, যাতে আপনি এন্ডপয়েন্ট দেখে নিজে রিপ্লে করতে পারেন। প্রতিটি পাঠানোয় একটি <code>X-FreeITSM-Delivery</code> হেডার থাকে, যার নম্বর প্রতি চেষ্টায় ও রিপ্লেতে একই, ফলে আপনার নিজের চালানো রিসিভার পুনরাবৃত্তি উপেক্ষা করতে পারে। Slack ও Teams-এর মতো চ্যাট টুল পারে না, এবং বার্তাটি দুবার দেখাবে।',
        'dp_title' => 'ডেটা সুরক্ষা',
        'dp_desc' => 'আপনার ওয়েবহুক সম্পর্কে FreeITSM ডিস্কে কী রাখে এবং কতদিন।',
        'enc_on_title' => 'ওয়েবহুক URL ও সাইনিং সিক্রেট সংরক্ষণের সময় এনক্রিপ্ট করা থাকে',
        'enc_on_body' => 'ওয়ার্কফ্লো এবং ডেলিভারি কিউ - দুই জায়গাতেই AES-256-GCM দিয়ে সংরক্ষিত। একটি ওয়েবহুক URL নিজেই একটি ক্রেডেনশিয়াল &mdash; যার কাছে এটি আছে সে আপনার চ্যানেলে পোস্ট করতে পারে &mdash; আর সাইনিং সিক্রেট প্রমাণ করে যে বার্তাটি সত্যিই আপনার কাছ থেকে এসেছে।',
        'enc_off_title' => 'কোনো এনক্রিপশন কী কনফিগার করা নেই &mdash; ওয়েবহুক URL ও সাইনিং সিক্রেট সাধারণ টেক্সটে সংরক্ষিত',
        'enc_off_body' => 'এনক্রিপশন কী ফাইল থাকলে FreeITSM এগুলো এনক্রিপ্ট করে, কিন্তু এই ইনস্টলে তা নেই, তাই আপনার ওয়েবহুক পুরোপুরি ব্যর্থ করার বদলে এগুলো যেমন আছে তেমনই সংরক্ষিত হচ্ছে। যে-কেউ ডেটাবেস বা তার ব্যাকআপ পড়তে পারে সে আপনার চ্যানেলে পোস্ট করতে এবং আপনার সিগনেচার জাল করতে পারে। এনক্রিপশন কী (<code>ENCRYPTION_KEY_PATH</code>) কনফিগার করুন এবং সংরক্ষিত মানগুলো এনক্রিপ্ট করতে প্রতিটি ওয়েবহুক ওয়ার্কফ্লো আবার সংরক্ষণ করুন।',
        'ret_label' => 'পাঠানো পেলোড রাখুন',
